import{z as n,x as i,o as t,c as d,q as l,j as B,D as e,d as s,s as o,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"数据流与解耦访存执行","description":"","frontmatter":{"title":"数据流与解耦访存执行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dataflow-dae.md","filePath":"cs/dataflow-dae.md","lastUpdated":1791413859000}'),p={name:"cs/dataflow-dae.md"};function m(D,a,C,c,u,h){const A=i("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="数据流与解耦访存执行" tabindex="-1">数据流与解耦访存执行 <a class="header-anchor" href="#数据流与解耦访存执行" aria-label="Permalink to &quot;数据流与解耦访存执行&quot;">​</a></h1><div class="epigraph"><p>指令何时执行由操作数到齐决定，而不是由 PC；解耦架构把产生地址的那条流与消耗数据的那条流拆开，用队列吸收缺失。</p><footer>—— 据 Dennis 的数据流；Smith, Decoupled Access/Execute Architectures, ISCA 1982 整理</footer></div><p><a href="/cs/vliw-epic">上一课</a> 仍按 PC（或 bundle）推进。<a href="/cs/tomasulo">Tomasulo</a> 已经在乱序核里用标签做局部数据流。本课不重打包 VLIW。缺口是 <strong>数据驱动的执行，以及 DAE：访问处理器与执行处理器之间用架构可见的队列解耦。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PC 驱动：下一条是内存里的下一字，即使它的数据还没到。<a href="/cs/mlp-memory-parallelism">MLP</a> 依赖乱序窗口碰巧装得下未来的 load。数据流机：点火规则是「token 齐」，理论上只剩真相关。缺口不是再宽的 bundle，而是<strong>把「算地址」与「用数据」拆成两条流，中间 FIFO 在 cache miss 时让执行侧继续做已到的运算，访问侧继续甩 load。</strong></p><p><span class="marginnote">「点火」可以想成做菜：每道工序写明「A、B 两种食材到齐就开火」，谁先备齐谁先做，完全不看菜谱页码——页码就是 PC。传统 CPU 是翻着页码做，食材没到只能干等或先跳过去再折返。</span></p><p><span class="marginnote">Smith 的 DAE：两个 PC、两套指令，编译器保证队列配对。它比纯数据流现实：控制流仍在，只是访存延迟被队列吸收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>纯数据流：指令存图，匹配单元等 token，齐则点火，结果再当 token 发出。DAE：Access 核跑 load/store 与归纳变量，Execute 核跑纯运算；队列满/空则停相应一侧。当代乱序核的 LQ 与 IQ 是同一思想的微结构版，但 ISA 仍是单一 PC。</p>',9)),(t(),B(r,null,{default:e(()=>[o(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E8%AE%BF%E9%97%AE%E6%B5%81%EF%BC%9A%E5%9C%B0%E5%9D%80%E4%B8%8E%20load%22%5D%20--%3E%20Q%5B%22%E6%95%B0%E6%8D%AE%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%E6%B5%81%EF%BC%9A%E7%BA%AF%E8%BF%90%E7%AE%97%22%5D%0A%20%20EX%20--%3E%20AQ%5B%22store%20%E6%95%B0%E6%8D%AE%E5%9B%9E%E8%AE%BF%E9%97%AE%E6%B5%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"这解释了为何乱序核要那么大的 LQ：它在模拟 DAE 的队列，而不改 ISA。VLIW 缺这个队列时，一记 miss 停整束。GPU 用大量 warp 换同一目的：延迟隐藏靠切换线程，不是数据流点火。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"用数字感受队列的价值：一次 cache miss 约两三百拍，一条运算 1 拍。没有队列时，执行流每碰上 miss 就整段干等；队列里若攒了 50 条操作数已齐的运算，miss 期间照样一拍出一条结果，等待被「藏」掉了大半。")],-1)),a[6]||(a[6]=E("p",null,"同一次 miss，三种机器各自的吸收方式：",-1)),(t(),B(r,null,{default:e(()=>[o(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22load%20%E6%9C%AA%E5%91%BD%E4%B8%AD%EF%BC%8C%E6%95%B0%E6%8D%AE%E8%BF%98%E8%A6%81%E7%AD%89%E5%87%A0%E7%99%BE%E6%8B%8D%22%5D%20--%3E%20A%5B%22DAE%EF%BC%9A%E8%AE%BF%E9%97%AE%E6%B5%81%E7%BB%A7%E7%BB%AD%E7%94%A9%E5%90%8E%E7%BB%AD%20load%EF%BC%8C%E6%89%A7%E8%A1%8C%E6%B5%81%E5%85%88%E7%AE%97%E9%98%9F%E5%88%97%E9%87%8C%E5%B7%B2%E5%88%B0%E8%B4%A6%E7%9A%84%22%5D%0A%20%20M%20--%3E%20B%5B%22%E4%B9%B1%E5%BA%8F%E6%A0%B8%EF%BC%9A%E7%AA%97%E5%8F%A3%E7%BB%A7%E7%BB%AD%E5%8F%91%E5%B0%84%E6%97%A0%E5%85%B3%E6%8C%87%E4%BB%A4%EF%BC%8CLQ%20%E5%85%85%E5%BD%93%E9%98%9F%E5%88%97%22%5D%0A%20%20M%20--%3E%20C%5B%22GPU%EF%BC%9A%E5%88%87%E5%88%B0%E5%8F%A6%E4%B8%80%E4%B8%AA%20warp%EF%BC%8C%E7%94%A8%E5%88%AB%E7%9A%84%E7%BA%BF%E7%A8%8B%E5%8D%A0%E4%BD%8F%E6%B5%81%E6%B0%B4%E7%BA%BF%22%5D%0A%20%20A%20--%3E%20R%5B%22%E4%B8%89%E7%A7%8D%E9%83%BD%E5%9C%A8%E5%9B%9E%E7%AD%94%EF%BC%9A%E7%AD%89%E5%BE%85%E6%9C%9F%E9%97%B4%E8%AE%A9%E8%B0%81%E5%B9%B2%E6%B4%BB%22%5D%0A%20%20B%20--%3E%20R%0A%20%20C%20--%3E%20R%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>本栏不把数据流图写成 ML 的 autograd 图。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计完整的 tagged-token 数据流 OS。下一课向量：回到 SIMD 格子，用 lane 同时对一组元素点火，控制流仍是一条。</p><p><span class="marginnote">初学者容易把 DAE 想成两个各跑各的独立 CPU。实际上两条流由编译器静态配对、共享一条架构可见的 FIFO：队列空则执行侧停，队列满则访问侧停——是互相牵制的接力，不是随便并发。</span></p><p>后课默认：延迟可以用窗口、队列或线程切换来藏。规则数组上，一条指令覆盖多 lane 比 MIMD 更密。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据流按 token 点火；DAE 用双流队列吸收访存延迟。</li><li>乱序 LQ 是单 ISA 下的 DAE 近似。</li><li>向量 lane 把 SIMD 铺成硬件数据通路，下一课。</li><li>出处：Dennis；Smith, <em>ISCA</em>, 1982。</li></ul>',7))])}const P=n(p,[["render",m]]);export{f as __pageData,P as default};
